/* THE FEED WINDOW: an hour, on the surfaces that gain entries. */
const cachedLive = unstable_cache(fetchLive, ["publication-archive-live", PUBLICATION], { revalidate: 3600 });

export async function getArchive(): Promise<Archive> {
  return merge(await cachedLive());
}

/* THE ENTRY PAGE'S LIST READ, ON THE ENTRY PAGE'S WINDOW. /entry/[slug] renders prev/next out of
 * the list, and Next takes the minimum window of everything a route renders through, so the
 * hourly key above would drag every prerendered entry page to 3600 whatever the route declared.
 * Separate key, separate window: the neighbours being up to a day old is cosmetic. */
const cachedLiveDaily = unstable_cache(fetchLive, ["publication-archive-daily", PUBLICATION], { revalidate: 86400 });

export async function getArchiveForEntry(): Promise<Archive> {
  return merge(await cachedLiveDaily());
}

/* ONE ENTRY, BY PRIMARY KEY. Not a scan of the cached list: the list is capped and cached, and an
 * entry page must not depend on either. (publication, slug) is the table's primary key, so this is
 * one indexed read, and then the daily list, and then the committed archive, so a slug that ever
 * existed keeps resolving. */
const cachedEntry = (slug: string) =>
  unstable_cache(
    async (): Promise<Entry | null> => {
      try {
        const sb = client();
        if (!sb) return null;
        const { data, error } = await sb
          .from("publication_posts")
          .select("*")
          .eq("publication", PUBLICATION)
          .eq("slug", slug)
          .maybeSingle();
        if (error) console.error(`[publication live] ${PUBLICATION}/${slug}: read failed (${error.message})`);
        if (error || !data) return null;
        return rowToEntry(data as Row);
      } catch (e) {
        console.error(`[publication live] ${PUBLICATION}/${slug}: read threw (${e instanceof Error ? e.message : String(e)})`);
        return null;
      }
    },
    ["publication-entry-live", PUBLICATION, slug],
    { revalidate: 86400 },
  )();

export async function getEntry(slug: string): Promise<Entry | undefined> {
  const committed = staticArchive.bySlug(slug);
  const direct = await cachedEntry(slug);
  if (direct) return { ...committed, ...direct };
  return (await getArchiveForEntry()).bySlug(slug) ?? committed;
}

