/**
 * The feed.
 *
 * ⛔ ALL FOUR PUBLICATIONS SHIPPED WITHOUT ONE. Verified live 2026-08-13: /rss.xml and /feed.xml
 * both 404'd on stillmornings, softmoney, usingitup and whyyourbrain. These are PUBLICATIONS —
 * the one thing a reader who likes one is most likely to want is a way to get the next entry
 * without coming back to look, and every one of them answered that with the 404 page.
 *
 * It also cost the only retention channel that needs nothing from us. The letter has never gone
 * out; a feed is the subscription that works the moment an entry lands, with no send, no list and
 * no deliverability.
 *
 * ── WHAT GOES IN AN ITEM ──────────────────────────────────────────────────────────────────────
 *
 * The narration lines ARE the body text — that is the contract in `src/lib/publication.ts`, not a
 * summary of the body, the body. So the full entry goes in `content:encoded` and a reader gets
 * the whole thing in their reader rather than a teaser and a click.
 *
 * ⛔ `pubDate` IS OMITTED WHERE THE LANE NEVER RECORDED A DATE, for the same reason sitemap.ts
 * omits `lastModified`: three of the four lanes have entries with `date: null`, and a build-time
 * `new Date()` standing in would tell every reader's client that a two-month-old entry was
 * published at deploy time — and would re-date the entire feed on every deploy, so every entry
 * would resurface as new, every time. A feed item with no date sorts by position instead, which
 * is honest. `n` is the archive's own 1-based order, so `guid` is stable regardless.
 */

/* The feed reads the live archive (src/lib/live.ts) on the same hourly window as the home page,
 * so a reader's client sees tonight's entry after the 21:30 sync with no deploy. `force-static`
 * keeps it a cached document regenerated on that window rather than a query per fetch. */
export const dynamic = "force-static";
export const revalidate = 3600;

const esc = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

const cdata = (s: string) => `<![CDATA[${s.replace(/]]>/g, "]]&gt;")}]]>`;

export async function GET() {
  const base = COPY.site.replace(/\/$/, "");
  const { publishedEntries: entries } = await getArchive();

  // Newest first where dates exist; the archive's own order otherwise.
  const sorted = [...entries].sort((a, b) => {
    if (a.date && b.date) return new Date(b.date).getTime() - new Date(a.date).getTime();
    if (a.date) return -1;
    if (b.date) return 1;
    return a.n - b.n;
  });

  const items = sorted
    .map((e) => {
      const url = `${base}/entry/${e.slug}`;
      const body = e.narration.map((line) => `<p>${esc(line)}</p>`).join("\n");
      /* `wide` is what EntryHero renders (EntryHero.tsx:108), so the feed shows the same frame
       * the page does. The paths in `wide` are already resolved by the site's own adapter — the
       * shell never derives them — so this only has to make them absolute for a reader that is
       * not on the site. */
      const img = e.wide ?? e.still;
      const frame = img
        ? `<p><img src="${esc(img.startsWith("http") ? img : `${base}${img}`)}" alt="${esc(frameAlt(e))}" /></p>\n`
        : "";
      return [
        "    <item>",
        `      <title>${cdata(e.hook)}</title>`,
        `      <link>${esc(url)}</link>`,
        `      <guid isPermaLink="true">${esc(url)}</guid>`,
        e.date ? `      <pubDate>${new Date(e.date).toUTCString()}</pubDate>` : null,
        `      <description>${cdata(e.caption || e.hook)}</description>`,
        `      <content:encoded>${cdata(frame + body)}</content:encoded>`,
        "    </item>",
      ]
        .filter(Boolean)
        .join("\n");
    })
    .join("\n");

  const xml = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<rss version="2.0" xmlns:content="http://purl.org/rss/1.0/modules/content/" xmlns:atom="http://www.w3.org/2005/Atom">',
    "  <channel>",
    `    <title>${cdata(COPY.name)}</title>`,
    `    <link>${esc(base)}</link>`,
    `    <description>${cdata(COPY.tagline)}</description>`,
    "    <language>en</language>",
    `    <atom:link href="${esc(`${base}/rss.xml`)}" rel="self" type="application/rss+xml" />`,
    items,
    "  </channel>",
    "</rss>",
  ].join("\n");

  return new Response(xml, {
    headers: {
      "content-type": "application/rss+xml; charset=utf-8",
      "cache-control": "public, max-age=3600, s-maxage=3600",
    },
  });
}

